import { useState } from "react";
import { Play, Save, CheckCircle, XCircle, Lock, User, Thermometer, FlaskConical } from "lucide-react";
import toast from "react-hot-toast";
import { clasificar, RANGOS } from "../utils/constants";

export default function Analisis() {
  const [estado,    setEstado]    = useState("idle");
  const [progreso,  setProgreso]  = useState(0);
  const [recepcion, setRecepcion] = useState({ finca:"", fecha:new Date().toISOString().split("T")[0], litros:"", operador:"" });
  const [manual,    setManual]    = useState({ ph:"", densidad:"", obs:"" });
  const [iot,       setIot]       = useState({ temp:null, ph:null });
  const [resultado, setResultado] = useState(null);

  const setR = k => e => setRecepcion(p => ({ ...p, [k]: e.target.value }));
  const setM = k => e => setManual(p    => ({ ...p, [k]: e.target.value }));

  const iniciar = async () => {
    if (!recepcion.finca || !recepcion.litros || !recepcion.operador) {
      toast.error("Complete los datos de recepción antes de iniciar.");
      return;
    }
    setEstado("analyzing");
    setResultado(null);
    setIot({ temp:null, ph:null });
    setProgreso(0);

    // Barra de progreso animada
    for (let i = 0; i <= 100; i += 5) {
      await new Promise(r => setTimeout(r, 70));
      setProgreso(i);
    }

    // ══ DEMO — reemplazar con: const { data } = await getUltimaMedicion(); ══
    const tempSensor = +(2 + Math.random() * 9).toFixed(1);
    const phSensor   = +(6.4 + Math.random() * 0.5).toFixed(2);
    // ══════════════════════════════════════════════════════════════════════════

    setIot({ temp: tempSensor, ph: phSensor });

    const phFinal  = manual.ph       ? parseFloat(manual.ph)       : phSensor;
    const densidad = manual.densidad ? parseFloat(manual.densidad) : null;
    const { apta, errores } = clasificar(tempSensor, phFinal, densidad);

    setResultado({ apta, errores, temp:tempSensor, ph:phFinal, densidad });
    setEstado("done");

    if (apta) toast.success("Leche APTA — compuerta → DERECHA ✓");
    else      toast.error("Leche NO APTA — compuerta → IZQUIERDA ✗");
  };

  const resetear = () => {
    setEstado("idle");
    setResultado(null);
    setIot({ temp:null, ph:null });
    setProgreso(0);
    setRecepcion({ finca:"", fecha:new Date().toISOString().split("T")[0], litros:"", operador:"" });
    setManual({ ph:"", densidad:"", obs:"" });
  };

  const Campo = ({ label, campoKey, type="text", placeholder="", icono:Icono=null, esManual=false }) => (
    <div>
      <label style={{ display:"block", fontSize:11, color:"rgba(255,255,255,0.45)", marginBottom:6 }}>
        {label}
      </label>
      <div style={{ position:"relative" }}>
        <input
          className="input-navy"
          type={type}
          placeholder={placeholder}
          value={esManual ? manual[campoKey] : recepcion[campoKey]}
          onChange={esManual ? setM(campoKey) : setR(campoKey)}
        />
        {Icono && (
          <Icono size={13} color="rgba(255,255,255,0.30)"
            style={{ position:"absolute", right:12, top:"50%", transform:"translateY(-50%)", pointerEvents:"none" }}/>
        )}
      </div>
    </div>
  );

  return (
    <div style={{ padding:"28px 32px", display:"flex", flexDirection:"column", gap:26, position:"relative" }} className="fade-up">

      {/* Fondo sutil */}
      <div style={{ position:"absolute", inset:0, background:"url('https://images.unsplash.com/photo-1500595046743-cd271d694d30?w=800&q=30') center/cover", opacity:0.05, pointerEvents:"none" }}/>

      {/* Título */}
      <div style={{ textAlign:"center", position:"relative" }}>
        <h1 style={{ fontFamily:"'Playfair Display',serif", fontSize:38, fontWeight:800, letterSpacing:"-0.02em", marginBottom:6 }}>
          Nuevo Análisis.
        </h1>
        <p style={{ fontSize:13, color:"rgba(255,255,255,0.45)" }}>
          Complete los datos y presione INICIAR para que el sistema evalúe la leche
        </p>
      </div>

      {/* Botón INICIAR */}
      <div style={{ display:"flex", justifyContent:"center", position:"relative" }}>
        <button
          className={`btn-iniciar${estado === "analyzing" ? " analizando" : ""}`}
          onClick={iniciar}
          disabled={estado === "analyzing"}
        >
          {estado === "analyzing"
            ? <><span className="spinner" style={{ width:20, height:20 }}/> Analizando...</>
            : <><Play size={20} fill="#fff"/> INICIAR ANÁLISIS</>
          }
        </button>
      </div>

      {/* Barra de progreso */}
      {estado === "analyzing" && (
        <div style={{ maxWidth:420, margin:"0 auto", width:"100%" }}>
          <div style={{ height:3, background:"rgba(255,255,255,0.08)", borderRadius:999, overflow:"hidden" }}>
            <div style={{ background:"linear-gradient(90deg,#2456a4,#6a9fd8)", height:"100%", width:`${progreso}%`, transition:"width 0.1s", borderRadius:999 }}/>
          </div>
          <p style={{ textAlign:"center", fontSize:11, color:"rgba(255,255,255,0.40)", marginTop:6 }}>
            Leyendo sensores ESP32... {progreso}%
          </p>
        </div>
      )}

      {/* 3 Columnas */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:20, position:"relative" }}>

        {/* Columna 1 — Datos de recepción */}
        <div>
          <p className="section-label">Datos de Recepción</p>
          <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
            <Campo label="Nombre de la Finca"  campoKey="finca"    placeholder="Finca El Roble"/>
            <Campo label="Fecha de Recepción"  campoKey="fecha"    type="date"/>
            <Campo label="Cantidad de Litros"  campoKey="litros"   type="number" placeholder="320"          icono={Lock}/>
            <Campo label="Nombre del Operador" campoKey="operador" placeholder="Carlos Méndez"              icono={User}/>
          </div>
        </div>

        {/* Columna 2 — Sistema IoT */}
        <div>
          <p className="section-label">Sistema IoT</p>
          <div className="navy-card" style={{ padding:"22px", display:"flex", flexDirection:"column", gap:16, minHeight:220, justifyContent:"center" }}>
            <div className="pill-sensor">
              <Thermometer size={19}/>
              <span>{iot.temp !== null ? `${iot.temp}°C` : "— °C"}</span>
            </div>
            <div className="pill-sensor">
              <FlaskConical size={19}/>
              <span>{iot.ph !== null ? `ph ${iot.ph}` : "ph —"}</span>
            </div>
            <div style={{ display:"flex", alignItems:"center", gap:8, fontSize:12, color: iot.temp !== null ? "#6a9fd8" : "rgba(255,255,255,0.35)" }}>
              <span style={{ width:7, height:7, borderRadius:"50%", display:"inline-block", background: iot.temp !== null ? "#6a9fd8" : "rgba(255,255,255,0.20)", boxShadow: iot.temp !== null ? "0 0 6px #6a9fd8" : "none" }}/>
              {iot.temp !== null ? "Sensor activo" : "Esperando inicio de análisis"}
            </div>
            {iot.temp !== null && (
              <p style={{ fontSize:11, color:"rgba(255,255,255,0.30)", fontStyle:"italic" }}>
                Capturado automáticamente por sensor ESP32
              </p>
            )}
          </div>
        </div>

        {/* Columna 3 — Datos manuales */}
        <div>
          <p className="section-label">Datos Manuales del Operador</p>
          <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
            <Campo label={`pH Manual (lactómetro) — Rango: ${RANGOS.ph.min}–${RANGOS.ph.max}`} campoKey="ph"       type="number" placeholder="6.65" esManual/>
            <Campo label={`Densidad g/cm³ — Rango: ${RANGOS.densidad.min}–${RANGOS.densidad.max}`} campoKey="densidad" type="number" placeholder="1.0310" esManual/>
            <div>
              <label style={{ display:"block", fontSize:11, color:"rgba(255,255,255,0.45)", marginBottom:6 }}>Observaciones</label>
              <textarea
                className="input-navy"
                rows={5}
                placeholder="Notas adicionales del operador..."
                value={manual.obs}
                onChange={setM("obs")}
                style={{ resize:"none" }}
              />
            </div>
          </div>
        </div>
      </div>

      {/* Panel de resultado */}
      {resultado && (
        <div className="navy-card fade-up" style={{ padding:"20px 24px" }}>
          <p className="section-label">Resultado del Análisis</p>
          <div style={{ display:"flex", alignItems:"center", gap:20, flexWrap:"wrap" }}>
            <div className={resultado.apta ? "result-apta" : "result-noapta"}>
              {resultado.apta ? <CheckCircle size={20}/> : <XCircle size={20}/>}
              {resultado.apta ? "LECHE APTA ✓" : "LECHE NO APTA ✗"}
            </div>
            <div style={{ flex:1 }}>
              <p style={{ fontSize:13, color:"rgba(255,255,255,0.70)" }}>
                <strong style={{ color:"#fff" }}>{recepcion.finca}</strong>
                {" | "}{recepcion.litros} L
                {" | "}{recepcion.operador}
                {" | "}{recepcion.fecha}
              </p>
              {!resultado.apta && resultado.errores.map((e, i) => (
                <p key={i} style={{ fontSize:12, color:"#fca5a5", marginTop:4 }}>⚠ {e}</p>
              ))}
              <p style={{ fontSize:11, color:"rgba(255,255,255,0.35)", marginTop:6 }}>
                {resultado.apta
                  ? "✓ Compuerta movida → DERECHA (canal APTA)"
                  : "✗ Compuerta movida → IZQUIERDA (canal RECHAZO)"}
              </p>
            </div>
            <div style={{ display:"flex", gap:12 }}>
              <button
                className="btn-navy"
                style={{ padding:"10px 20px", fontSize:13, borderRadius:9 }}
                onClick={() => { toast.success("Registro guardado correctamente."); resetear(); }}
              >
                <Save size={15}/> Guardar Registro
              </button>
              <button className="btn-outline-white" onClick={resetear}>Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
